import React,{useEffect,useMemo,useState} from "react";
import{Search,ShieldCheck,Globe2,Activity,AlertTriangle,Boxes,Waypoints,Clock3,ChevronRight,RefreshCw,LogOut,Command,Menu,X,Plus,UserRound,Layers3,BrainCircuit,ArrowUpRight,LockKeyhole,Eye,CheckCircle2,PanelLeftClose,Radar,ShieldAlert,TriangleAlert,Target,SlidersHorizontal,Cpu,Inbox,Sparkles}from"lucide-react";
import{AreaChart,Area,ResponsiveContainer,Tooltip,XAxis,YAxis,CartesianGrid,BarChart,Bar}from"recharts";

const api="";
const cx=(...x)=>x.filter(Boolean).join(" ");
const esc=(v)=>String(v??"");
async function req(path,opts={}){
 const h=new Headers(opts.headers||{});
 const r=await fetch(api+path,{...opts,headers:h,credentials:"include"});if(r.status===401){location.reload()}return r;
}
function App(){
 const[authenticated,setAuthenticated]=useState(true);
 const[me,setMe]=useState(null),[dash,setDash]=useState(null),[assets,setAssets]=useState([]),[exposure,setExposure]=useState([]),[ctem,setCtem]=useState([]),[impact,setImpact]=useState([]),[story,setStory]=useState([]),[selected,setSelected]=useState(null),[mssp,setMssp]=useState({tenants:[],summary:{}}),[msspTrend,setMsspTrend]=useState({tenants:[]}),[controls,setControls]=useState({coverage:{},controls:[],choke_points:[]}),[aiStatus,setAiStatus]=useState(null),[pathAI,setPathAI]=useState(null),[pathAILoading,setPathAILoading]=useState(false),[drp,setDrp]=useState({events:[],summary:{}}),[brandAI,setBrandAI]=useState(null),[infra,setInfra]=useState(null),[infraGraph,setInfraGraph]=useState(null),[easm,setEasm]=useState({summary:{},inventory:[],changes:{},risk:{}}),[graph,setGraph]=useState({nodes:[],edges:[],top_risk_paths:[]}),[search,setSearch]=useState(""),[active,setActive]=useState("overview"),[loading,setLoading]=useState(false),[sidebar,setSidebar]=useState(true),[target,setTarget]=useState(""),[discovery,setDiscovery]=useState(null),[question,setQuestion]=useState(""),[copilot,setCopilot]=useState(null),[login,setLogin]=useState({email:"",password:""}),[loginError,setLoginError]=useState("");
 const load=async()=>{setLoading(true);try{const [m,d,a,e,c,b,s,g,mssp,msspTrend,controls,aiStatus,drp,easm]=await Promise.all([req("/api/v1/auth/me"),req("/api/v1/dashboard"),req("/api/v1/radar"),req("/api/v1/exposure"),req("/api/v1/exposure/ctem"),req("/api/v1/exposure/business-impact"),req("/api/v1/exposure/storyline"),req("/api/v1/graph"),req("/api/v1/mssp/command-center"),req("/api/v1/mssp/command-center/trend"),req("/api/v1/graph/control-coverage"),req("/api/v1/exposure/ai/status"),req("/api/v1/digital-risk"),req("/api/v1/easm/overview")]);setMe(await m.json());setDash(await d.json());setAssets((await a.json()).assets||[]);setExposure(await e.json());setCtem((await c.json()).items||[]);setImpact((await b.json()).items||[]);setStory((await s.json()).events||[]);setGraph(await g.json());setMssp(mssp.ok?await mssp.json():{tenants:[],summary:{}});setMsspTrend(msspTrend.ok?await msspTrend.json():{tenants:[]});setControls(controls.ok?await controls.json():{coverage:{},controls:[],choke_points:[]});setAiStatus(aiStatus.ok?await aiStatus.json():null);setDrp(drp.ok?await drp.json():{events:[],summary:{}});setEasm(easm.ok?await easm.json():{summary:{},inventory:[],changes:{},risk:{}})}finally{setLoading(false)}};
 useEffect(()=>{load().catch(()=>setAuthenticated(false))},[]);
 const filtered=useMemo(()=>assets.filter(a=>esc(a.value).toLowerCase().includes(search.toLowerCase())||esc(a.type).toLowerCase().includes(search.toLowerCase())),[assets,search]);
 const trend=useMemo(()=>{const base=dash?.exposure_score??0;return Array.from({length:7},(_,i)=>({day:"D-"+(6-i),score:Math.max(0,Math.round(base+(i-3)*2))}))},[dash]);
 const doLogin=async e=>{e.preventDefault();setLoginError("");const r=await fetch("/api/v1/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(login)});const d=await r.json();if(!r.ok)return setLoginError(d.detail||"Credenciais inválidas");setAuthenticated(true)};
 const runDiscovery=async()=>{if(!target)return;setDiscovery({loading:true});const r=await req("/api/v1/discovery",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({target,checks:["dns","http","tls","ct","ports"]})});setDiscovery(await r.json())};
 const ask=async()=>{if(!question)return;const r=await req("/api/v1/exposure/copilot?question="+encodeURIComponent(question));setCopilot(await r.json())};
 const logout=async()=>{await req("/api/v1/auth/logout",{method:"POST"});setAuthenticated(false)};
 if(!authenticated)return <Login login={login} setLogin={setLogin} onSubmit={doLogin} error={loginError}/>;
 return <div className="app-shell">
  <aside className={cx("sidebar",!sidebar&&"collapsed")}><div className="side-brand"><div className="panther"><img src="/assets/bsa-panther.svg" alt="Be Safe"/></div>{sidebar&&<div><b>BE SAFE</b><span>ASM / EXPOSURE</span></div>}</div>
   <nav>{[["overview","Exposure Overview",Activity],["easm","External Surface",Radar],["vuln","Vulnerabilities",ShieldAlert],["risk","Risk Intelligence",TriangleAlert],["ctem","CTEM",Target],["queue","CTEM Queue",Waypoints],["policy","Risk Policy",SlidersHorizontal],["tech","Technology",Cpu],["surface","Attack Surface",Globe2],["assets","Asset Inventory",Boxes],["story","Change Storyline",Clock3],["admin","Governance",Layers3]].map(([id,label,Icon])=><button key={id} className={cx("nav-item",active===id&&"active")} onClick={()=>setActive(id)}><Icon size={18}/>{sidebar&&<><span>{label}</span>{(id==="ctem"||id==="queue")&&ctem.length>0&&<em>{ctem.length}</em>}</>}</button>)}</nav>
   {sidebar&&<div className="side-bottom"><div className="tenant-card"><div className="eyebrow">TENANT</div><strong>{me?.tenant_id||"tenant-demo"}</strong><span>{me?.role||"analyst"} · protected</span></div><button className="nav-item" onClick={logout}><LogOut size={17}/>Sair</button></div>}
  </aside>
  <main className="workspace">{loading&&<div className="top-progress" aria-label="Atualizando dados"><i/></div>}<header className="topbar"><button className="icon-btn" aria-label={sidebar?"Recolher navegação":"Expandir navegação"} title={sidebar?"Recolher navegação":"Expandir navegação"} onClick={()=>setSidebar(!sidebar)}>{sidebar?<PanelLeftClose size={19}/>:<Menu size={19}/>}</button><div className="crumb"><span>Be Safe ASM</span><ChevronRight size={14}/><b>{active==="overview"?"Exposure Overview":active==="easm"?"External Attack Surface":active==="vuln"?"Vulnerability Intelligence":active==="risk"?"Risk Intelligence":active==="ctem"?"Risk-Based CTEM":active==="queue"?"CTEM Queue":active==="policy"?"Risk Policy Studio":active==="tech"?"Technology Intelligence":active==="surface"?"Attack Surface":active==="assets"?"Asset Inventory":active==="story"?"Change Storyline":"Governance"}</b></div><div className="top-actions"><div className="status"><i/> LIVE INTELLIGENCE</div><button className="icon-btn" aria-label="Atualizar inteligência" title="Atualizar inteligência" onClick={load}><RefreshCw size={17} className={loading?"spin":""}/></button><div className="avatar">{(me?.name||"M").slice(0,1).toUpperCase()}</div></div></header>
   <div className="content">
    {active==="overview"&&<Overview dash={dash} exposure={exposure} assets={assets} ctem={ctem} impact={impact} trend={trend} onAsset={setSelected} graph={graph} mssp={mssp} msspTrend={msspTrend} controls={controls} drp={drp} target={target} setTarget={setTarget} infra={infra} setInfra={setInfra} infraGraph={infraGraph} setInfraGraph={setInfraGraph} role={me?.role}/>}
    {active==="easm"&&<EASM easm={easm} onAsset={setSelected}/>}
    {active==="vuln"&&<VulnerabilityIntel/>}
    {active==="risk"&&<RiskIntel/>}
    {active==="ctem"&&<CtemIntel/>}
    {active==="policy"&&<RiskPolicyStudio/>}
    {active==="tech"&&<TechnologyIntel/>}
    {active==="surface"&&<Surface assets={assets} filtered={filtered} search={search} setSearch={setSearch} target={target} setTarget={setTarget} runDiscovery={runDiscovery} discovery={discovery} onAsset={setSelected}/>}
    {active==="assets"&&<Assets assets={filtered} search={search} setSearch={setSearch} onAsset={setSelected}/>}
    {active==="queue"&&<CTEM items={ctem} onAsset={setSelected}/>}
    {active==="story"&&<Story events={story} onAsset={setSelected}/>}
    {active==="admin"&&<Governance me={me}/>}
    <section className="copilot"><div className="copilot-icon"><BrainCircuit size={20}/></div><div className="copilot-body"><div className="eyebrow">EXPOSURE COPILOT <span>{aiStatus?.enabled?"LOCAL AI · "+aiStatus.model:"RULE-BASED"}</span></div><strong>Pergunte sobre sua superfície</strong><div className="copilot-input"><input value={question} onChange={e=>setQuestion(e.target.value)} onKeyDown={e=>e.key==="Enter"&&ask()} placeholder='“O que mudou?”  “Quais ativos estão sem owner?”  “O que está mais exposto?”'/><button onClick={ask}><Command size={16}/> Perguntar</button></div>{copilot&&<div className="copilot-answer"><b>{copilot.answer}</b><div>{(copilot.evidence||[]).slice(0,5).map(x=><span key={x.asset_id}>{x.asset} · confidence {x.confidence}</span>)}</div></div>}</div></section>
   </div>
  </main>
  {selected&&<AssetDrawer id={selected} onClose={()=>setSelected(null)}/>}
 </div>
}
function Login({login,setLogin,onSubmit,error}){return <div className="login-page"><div className="login-glow"/><div className="login-panel"><div className="login-brand"><div className="panther big"><img src="/assets/bsa-panther.svg" alt="Be Safe"/></div><div><b>BE SAFE</b><span>ATTACK SURFACE MANAGEMENT</span></div></div><div className="eyebrow">SECURE CONSOLE</div><h1>Know your surface.<br/><i>Reduce your exposure.</i></h1><p>External exposure intelligence com evidência, contexto e ação.</p><form onSubmit={onSubmit}><label>E-mail<input type="email" autoComplete="email" required value={login.email} onChange={e=>setLogin({...login,email:e.target.value})} placeholder="you@company.com"/></label><label>Senha<input type="password" autoComplete="current-password" required value={login.password} onChange={e=>setLogin({...login,password:e.target.value})} placeholder="••••••••••••"/></label>{error&&<div className="error">{error}</div>}<button className="primary wide">Entrar na plataforma <ArrowUpRight size={17}/></button></form><small>Tenant isolation · RBAC · audit trail</small></div><div className="login-art"><div className="radar"><span/><span/><span/><span/></div><div className="art-card"><div className="eyebrow">EXPOSURE SCORE</div><strong>62</strong><span>contextual posture</span></div></div></div>}
function AttackRadar({graph,assets,onAsset}){const[mode,setMode]=useState("risk");const[kind,setKind]=useState("all");const[band,setBand]=useState("all");const[selectedPath,setSelectedPath]=useState(0);const[query,setQuery]=useState("");const[simulation,setSimulation]=useState(null);const[simulating,setSimulating]=useState(false);const[planner,setPlanner]=useState(false);const[planned,setPlanned]=useState(false);const[planBusy,setPlanBusy]=useState(false);const[planItems,setPlanItems]=useState([]);const paths=graph.top_risk_paths||[];const nodes=graph.nodes||[];const edges=graph.edges||[];const visible=nodes.filter(n=>(kind==="all"||n.kind===kind)&&(band==="all"||n.risk_band===band)&&(query===""||n.label.toLowerCase().includes(query.toLowerCase())));const byId=Object.fromEntries(nodes.map(n=>[n.id,n]));const active=paths[selectedPath];const pathIds=new Set(active?.nodes||[]);const pts=visible.slice(0,28).map((n,i)=>{const a=(i/Math.max(visible.length,1))*Math.PI*2;const rr=34+(i%4)*7;return{...n,x:50+Math.cos(a)*rr,y:50+Math.sin(a)*rr}});const getAsset=n=>assets.find(a=>a.value===n.label);return <section className="panel attack-radar explorer"><div className="explorer-head"><div><PanelHead title="Attack Path Explorer" meta={nodes.length+" nodes · "+edges.length+" edges"}/><div className="explorer-tabs"><button className={mode==="surface"?"on":""} onClick={()=>setMode("surface")}>SURFACE</button><button className={mode==="risk"?"on":""} onClick={()=>setMode("risk")}>RISK PATH</button><button className={mode==="impact"?"on":""} onClick={()=>setMode("impact")}>BUSINESS IMPACT</button></div></div><div className="graph-controls"><input className="graph-search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar node..."/><select value={kind} onChange={e=>setKind(e.target.value)}><option value="all">All nodes</option>{[...new Set(nodes.map(n=>n.kind))].map(k=><option key={k} value={k}>{k}</option>)}</select><select value={band} onChange={e=>setBand(e.target.value)}><option value="all">All risk</option><option value="critical">Critical</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select></div></div><div className="explorer-body"><div className="radar-canvas"><div className="radar-grid"/><svg className="graph-lines" viewBox="0 0 100 100" preserveAspectRatio="none">{edges.slice(0,70).map((e,i)=>{const a=pts.find(p=>p.id===e.source_id),b=pts.find(p=>p.id===e.target_id);if(!a||!b)return null;const activeEdge=pathIds.has(e.source_id)&&pathIds.has(e.target_id);return <line key={i} x1={a.x} y1={a.y} x2={b.x} y2={b.y} className={activeEdge?"path-edge":e.confidence>=85?"risk-edge":"soft-edge"}/>})}</svg><div className="radar-sweep"/><div className="radar-core"><ShieldCheck size={24}/><span>{mode==="risk"?"RISK":"SURFACE"}</span></div>{pts.map(a=><button key={a.id} className={cx("graph-node",a.risk_band==="critical"&&"critical-node",pathIds.has(a.id)&&"path-node")} style={{left:a.x+"%",top:a.y+"%"}} onClick={()=>{const hit=getAsset(a);if(hit)onAsset(hit.asset_id||hit.id)}}><span className="node-pulse"/><b>{a.label?.split(".")[0]}</b><small>{a.kind} · {a.risk_score||0}</small></button>)}<div className="radar-legend"><span><i className="lg-pink"/>selected path</span><span><i className="lg-green"/>evidence</span><span><i className="lg-gray"/>observed</span></div></div><aside className="path-inspector">{active?<><div className="eyebrow">SELECTED ATTACK PATH</div><div className="path-score"><strong>{active.score}</strong><span>{active.band}</span><em>impact {Math.max(...(active.explanation.evidence||[]).map(x=>x.impact||0),0)}%</em></div><div className="path-chain">{active.labels.map((label,i)=><div key={label+"-"+i} className="chain-item"><b>{i+1}</b><div><strong>{label}</strong><span>{active.kinds[i]}</span></div>{i<active.labels.length-1&&<ChevronRight size={14}/>}</div>)}</div><div className="inspector-section"><h4>WHY THIS PATH</h4>{active.explanation.reasons.map(x=><p key={x}>+ {x}</p>)}</div><button className="planner-toggle" onClick={()=>setPlanner(!planner)}>{planner?"CLOSE PLANNER":"OPEN REMEDIATION PLANNER"}</button><div className="ctem-mini"><div className="eyebrow">CTEM PLAN</div>{planItems.map(p=><div className="ctem-mini-row" key={p.plan_id}><div><b>{p.asset}</b><span>{p.status} · {p.priority_score}</span></div><strong>-{p.risk_reduction}</strong></div>)}</div>{planner&&<div className="planner-list">{paths.slice(0,6).map((p,i)=><button key={i} className="planner-path" onClick={()=>setSelectedPath(i)}><div><b>PATH {i+1}</b><span>{p.labels.join(" → ")}</span></div><strong>{p.score}</strong></button>)}</div>}<button className="planner-approve" disabled={planBusy||planned} onClick={async()=>{setPlanBusy(true);const assetIds=(active?.nodes||[]).map(id=>byId[id]).filter(n=>n?.kind!=="internet"&&n?.kind!=="finding").map(n=>{const a=assets.find(x=>x.value===n.label);return a?.asset_id||a?.id}).filter(Boolean);const findingIds=(active?.nodes||[]).filter(id=>byId[id]?.kind==="finding");const rr=await req("/api/v1/exposure/ctem/plan",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({asset_ids:assetIds,finding_ids:findingIds})});if(rr.ok){setPlanned(true);setPlanItems((await rr.json()).items||[])}setPlanBusy(false)}}>{planned?"✓ PLANNED IN CTEM":planBusy?"PLANNING…":"APPROVE & SEND TO CTEM"}</button><button className="whatif-btn" disabled={simulating} onClick={async()=>{setSimulating(true);const ids=active.nodes.filter(id=>byId[id]?.kind==="finding");const rr=await req("/api/v1/graph/simulate",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({path:active.nodes,finding_node_ids:ids})});setSimulation(await rr.json());setSimulating(false)}}>{simulating?"SIMULATING…":"WHAT IF · SIMULATE REMEDIATION"}</button>{simulation&&<div className="simulation-card"><div><span>RISK</span><b>{simulation.before} → {simulation.after}</b></div><div><span>REDUCTION</span><b>{simulation.reduction_percent}%</b></div><div className="simulation-bar"><i style={{width:simulation.reduction_percent+"%"}}/></div></div>}<div className="inspector-section"><h4>BUSINESS IMPACT</h4><div className="impact-bar"><i style={{width:Math.max(...(active.explanation.evidence||[]).map(x=>x.impact||0),0)+"%"}}/></div><p className="impact-note">Prioridade combina risco, confiança da evidência e impacto potencial.</p><h4>WEAKEST LINK</h4>{active.explanation.weakest_link?<div className="weak-link"><b>{active.explanation.weakest_link.from} → {active.explanation.weakest_link.to}</b><span>{active.explanation.weakest_link.relationship} · confidence {active.explanation.weakest_link.confidence}%</span></div>:<span className="muted">No weak link identified.</span>}</div><div className="path-switch">{paths.slice(0,5).map((p,i)=><button key={i} className={i===selectedPath?"sel":""} onClick={()=>setSelectedPath(i)}><b>PATH {i+1}</b><span>{p.score}</span></button>)}</div></>:<div className="empty-stage">Nenhum Risk Path material detectado.</div>}</aside></div></section>}function MSSPCommandCenter({data,trend,controls,onTenant}){const rows=data?.tenants||[];const trendRows=trend?.tenants||[];const s=data?.summary||{};return <section className="panel mssp-center"><PanelHead title="MSSP Command Center" meta={rows.length+" tenants"}/><div className="mssp-kpis"><div><b>{s.critical_tenants||0}</b><span>CRITICAL TENANTS</span></div><div><b>{s.open_findings||0}</b><span>OPEN FINDINGS</span></div><div><b>{s.ctem_plans||0}</b><span>CTEM PLANS</span></div><div><b>{s.overdue||0}</b><span>OVERDUE</span></div><div><b>{s.in_progress||0}</b><span>IN PROGRESS</span></div><div><b>{s.remediated||0}</b><span>REMEDIATED</span></div><div><b>{s.sla_compliance||100}%</b><span>SLA COMPLIANCE</span></div><div><b>{s.sla_breaches||0}</b><span>SLA BREACHES</span></div><div><b>{s.risk_residual||0}</b><span>RESIDUAL RISK</span></div><div><b>-{s.risk_reduction_30d||0}</b><span>RISK REDUCTION 30D</span></div></div><div className="tenant-table">{rows.map(t=><button key={t.tenant_id} onClick={()=>onTenant?.(t.tenant_id)}><div><strong>{t.tenant}</strong><span>{t.assets} assets · {t.open_findings} findings · {t.critical_findings||0} critical</span></div><em className={t.risk>=80?"r-critical":t.risk>=60?"r-high":""}>{t.risk}</em><small>{t.ctem} CTEM · {t.in_progress||0} active · {t.remediated||0} done · {t.avg_ctem_age_days||0}d avg</small><small className="tenant-sla">SLA {t.sla_compliance||100}% · residual {t.risk_residual||0} · 30d -{t.risk_reduction_30d||0}</small></button>)}</div><div className="control-strip"><div><b>{controls?.coverage?.coverage_percent||0}%</b><span>CONTROL COVERAGE</span></div><div><b>{controls?.choke_points?.length||0}</b><span>CHOKE POINTS</span></div><div><b>{(controls?.controls||[]).length}</b><span>CONTROL TYPES</span></div></div><div className="mssp-trend"><div className="eyebrow">90D REMEDIATION HISTORY</div><div className="mssp-spark-row">{trendRows.slice(0,8).map(t=><div className="mssp-spark" key={t.tenant_id}><span>{t.tenant}</span><div>{(t.events||[]).slice(-8).map((e,i)=><i key={i} style={{height:Math.max(8,Math.min(100,(e.risk_reduction||0)*2+12))+"%"}}/> )}</div></div>)}</div></div></section>}
function Overview({dash,exposure,assets,ctem,impact,trend,onAsset,graph,mssp,msspTrend,controls,drp,role,target,setTarget,infra,setInfra,infraGraph,setInfraGraph}){return <><PageTitle eyebrow="EXPOSURE INTELLIGENCE" title={<>Sua superfície, <i>explicada.</i></>} sub="Uma visão operacional da exposição externa, do risco ao próximo passo."/>{["superadmin","admin","manager"].includes(role)&&<><MSSPCommandCenter data={mssp} trend={msspTrend} controls={controls}/><section className="panel infra-panel"><PanelHead title="Infrastructure Intelligence" meta="DNS · IP · ASN · TLS · FAVICON · REDIRECTS"/><div className="infra-flow"><span>DOMAIN</span><i>→</i><span>IP / ASN</span><i>→</i><span>CERTIFICATE</span><i>→</i><span>RELATED INFRA</span></div><button className="infra-action" onClick={async()=>{const t=target||assets?.[0]?.value;if(!t)return;const rr=await req("/api/v1/discovery/"+encodeURIComponent(t)+"/infrastructure");setInfra(rr.ok?await rr.json():null);const gg=await req("/api/v1/discovery/"+encodeURIComponent(t)+"/infrastructure/graph");setInfraGraph(gg.ok?await gg.json():null)}}>ANALYZE TARGET INFRASTRUCTURE</button>{infraGraph&&<div className="infra-graph"><div className="infra-graph-head"><span>OBSERVED INFRASTRUCTURE GRAPH</span><b>{infraGraph.summary?.nodes||0} NODES · {infraGraph.summary?.edges||0} EDGES</b></div><div className="infra-graph-canvas">{infraGraph.nodes?.map((n,i)=><div className={"infra-node "+(i===0?"root":"")} key={n.id} style={{left:(50+42*Math.cos(i*2.4))+"%",top:(50+38*Math.sin(i*2.4))+"%"}}><b>{n.type}</b><span>{n.label}</span><em>{n.confidence}%</em></div>)}{infraGraph.edges?.map((e,i)=><div className="infra-edge" key={i}><span>{e.confidence}% · {e.type}</span></div>)}</div></div>}{infra&&<div className="infra-result"><div><b>{infra.cluster_strength}%</b><span>CLUSTER STRENGTH</span></div><div><b>{infra.link_count}</b><span>LINKS</span></div><small>{(infra.links||[]).map(x=>x.type+": "+x.value).join(" · ")||"No correlation links observed."}</small></div>}<div className="brand-note">Shared infrastructure is evidence of correlation, not proof of common ownership or maliciousness. BSA keeps confidence and validation requirements visible.</div></section><section className="panel brand-panel"><PanelHead title="Brand Protection Intelligence" meta="VISUAL · TEXT · AI · EVIDENCE"/><div className="brand-grid"><div><b>65%</b><span>VISUAL WEIGHT</span></div><div><b>35%</b><span>TEXT WEIGHT</span></div><div><b>{drp.summary?.takedown_candidates||0}</b><span>TAKEDOWN READY</span></div></div><div className="brand-note">Impersonation is classified only from evidence. Local AI explains the signal; it does not override deterministic scoring.</div></section><section className="panel drp-panel"><PanelHead title="Digital Risk Protection" meta="DRP · CTI · TAKEDOWN"/><div className="drp-kpis"><div><b>{drp.summary?.total||0}</b><span>EXTERNAL THREATS</span></div><div><b>{drp.summary?.critical||0}</b><span>CRITICAL</span></div><div><b>{drp.summary?.takedown_candidates||0}</b><span>TAKEDOWN CANDIDATES</span></div><div><b>{drp.summary?.open||0}</b><span>OPEN</span></div></div><div className="drp-cats">{Object.entries(drp.summary?.by_category||{}).map(([k,v])=><span key={k}>{k}<b>{v}</b></span>)}</div></section></>}<div className="kpis">{[["Exposure Score",dash?.exposure_score??"—","contextual"],["Assets",dash?.total_assets??"—","discovered"],["Open Findings",dash?.open_findings??"—","needs action"],["Critical",dash?.critical_findings??"—","priority"],["Changes 24h",dash?.changes_24h??"—","continuous"]].map(([l,v,s],i)=><div className={cx("kpi",i===0&&"hero-kpi")} key={l}><span>{l}</span><strong>{v}</strong><small>{s}</small></div>)}</div><div className="grid-main"><AttackRadar graph={graph} assets={assets} onAsset={onAsset}/><section className="panel chart-panel"><PanelHead title="Exposure posture" meta="7-day signal"/><div className="chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trend}><defs><linearGradient id="pinkFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#ff2d84" stopOpacity=".32"/><stop offset="100%" stopColor="#ff2d84" stopOpacity="0"/></linearGradient></defs><CartesianGrid stroke="#232936" vertical={false}/><XAxis dataKey="day" stroke="#687080" tickLine={false} axisLine={false}/><YAxis stroke="#687080" tickLine={false} axisLine={false}/><Tooltip contentStyle={{background:"#11151e",border:"1px solid #2b3240",borderRadius:12,color:"#fff"}}/><Area type="monotone" dataKey="score" stroke="#ff2d84" strokeWidth={3} fill="url(#pinkFill)"/></AreaChart></ResponsiveContainer></div></section><section className="panel"><PanelHead title="Top exposure" meta="risk-ranked"/><div className="rank-list">{exposure.slice(0,6).map(x=><button className="rank" key={x.asset_id} onClick={()=>onAsset(x.asset_id)}><div><strong>{x.asset}</strong><span>{x.band} · {x.rationale?.[0]||"contextual"}</span></div><b>{x.score}</b></button>)}</div></section></div><div className="grid-main lower"><section className="panel"><PanelHead title="CTEM queue" meta={ctem.length+" items"}/>{ctem.slice(0,5).map(x=><button className="row" key={x.asset_id} onClick={()=>onAsset(x.asset_id)}><div className="dot pink-dot"/><div><strong>{x.asset}</strong><span>{x.next_action} · {x.owner||"unowned"}</span></div><b>{x.priority_score}</b><ChevronRight size={16}/></button>)}</section><section className="panel"><PanelHead title="Business impact" meta="context"/>{impact.slice(0,5).map(x=><div className="row" key={x.asset_id}><div className="dot amber-dot"/><div><strong>{x.asset}</strong><span>{x.business_unit||"Unknown"} · {x.environment}</span></div><b>{x.impact_index}</b></div>)}</section></div></>}
function PageTitle({eyebrow,title,sub}){return <div className="page-title"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{sub}</p></div><div className="secure"><ShieldCheck size={16}/> Evidence-first</div></div>}
function PanelHead({title,meta}){return <div className="panel-head"><h3>{title}</h3><span>{meta}</span></div>}
function EmptyState({title="Nenhum dado ainda",text="Assim que houver evidência suficiente, os resultados aparecem aqui.",compact=false}){return <div className={cx("empty-pro",compact&&"compact")}><div className="empty-pro-icon"><Inbox size={compact?16:20}/></div><div><strong>{title}</strong><span>{text}</span></div></div>}
function Assets({assets,search,setSearch,onAsset}){return <><PageTitle eyebrow="ASSET INVENTORY" title={<>Conheça cada <i>ativo.</i></>} sub="Inventário vivo com ownership, confidence e exposição contextual."/><div className="toolbar-pro"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar hostname, domínio, IP ou tipo..."/><span>{assets.length} ativos</span></div><div className="panel table-panel"><table><thead><tr><th>Asset</th><th>Type</th><th>Ownership</th><th>Confidence</th><th>Criticality</th><th>Exposure</th><th/></tr></thead><tbody>{assets.length?assets.map(a=><tr key={a.asset_id} onClick={()=>onAsset(a.asset_id)}><td><strong>{a.value}</strong><small>{a.dna}</small></td><td><span className="tag">{a.type}</span></td><td>{a.owner||<span className="warn">Unowned</span>}</td><td><Meter value={a.confidence}/></td><td><span className="critical">{a.criticality}/5</span></td><td><span className={cx("score-pill",a.change_type!=="stable"&&"hot")}>{a.change_type==="stable"?"stable":"changed"}</span></td><td><ChevronRight size={16}/></td></tr>):<tr className="empty-table-row"><td colSpan="7"><EmptyState title="Nenhum ativo encontrado" text="Ajuste a busca ou execute discovery para popular o inventário." compact/></td></tr>}</tbody></table></div></>}
function RiskPolicyStudio(){const [p,setP]=useState(null);const [draft,setDraft]=useState({});const [msg,setMsg]=useState("");useEffect(()=>{req("/api/v1/risk/policy").then(async r=>{if(r.ok){const d=await r.json();setP(d.policy);setDraft(d.policy)}})},[]);const fields=["likelihood_weight","impact_weight","confidence_weight","internet_multiplier","production_multiplier","remote_access_multiplier","compensating_control_reduction"];return <><PageTitle eyebrow="RISK POLICY STUDIO" title={<>Calibre o risco. <i>Veja antes de publicar.</i></>} sub="Política isolada por tenant, com validação e simulação local dos pesos."/><section className="panel policy-studio"><PanelHead title="Tenant risk policy" meta={p?("v"+p.version+" · "+p.tenant_id):"LOADING"}/><div className="policy-grid">{fields.map(k=><label><span>{k.replaceAll("_"," ").toUpperCase()}</span><input type="number" step="0.05" value={draft[k]??""} onChange={e=>setDraft({...draft,[k]:Number(e.target.value)})}/></label>)}</div><div className="policy-sim"><b>WEIGHT SUM</b><strong>{((draft.likelihood_weight||0)+(draft.impact_weight||0)+(draft.confidence_weight||0)).toFixed(2)}</strong><span>{((draft.likelihood_weight||0)+(draft.impact_weight||0)+(draft.confidence_weight||0))===1?"VALID":"MUST EQUAL 1.00"}</span></div><button className="policy-save" onClick={async()=>{setMsg("VALIDATING…");const r=await req("/api/v1/risk/policy",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(draft)});setMsg(r.ok?"POLICY VALIDATED":"POLICY REJECTED")}}>{msg||"VALIDATE POLICY"}</button></section></>}

