function TechnologyIntel(){const [target,setTarget]=useState("");const [data,setData]=useState(null);const [loading,setLoading]=useState(false);return <><PageTitle eyebrow="TECHNOLOGY INTELLIGENCE" title={<>Descubra a tecnologia. <i>Não invente a versão.</i></>} sub="Fingerprint conservador para transformar exposição externa em identificação confiável de componentes."/><section className="panel tech-query"><PanelHead title="Technology discovery" meta="VERSION-AWARE"/><div><input value={target} onChange={e=>setTarget(e.target.value)} placeholder="domínio autorizado"/><button onClick={async()=>{if(!target.trim())return;setLoading(true);const r=await req("/api/v1/technologies/intelligence/"+encodeURIComponent(target));setData(r.ok?await r.json():null);setLoading(false)}}>{loading?"ANALYZING…":"ANALYZE TECHNOLOGY"}</button></div></section>{!data&&<div className="analysis-ready"><Sparkles size={17}/><div><b>Pronto para analisar</b><span>Informe um domínio autorizado para identificar tecnologias e evidências sem inferir versões sem confirmação.</span></div></div>}{data&&<><div className="vuln-kpis">{[["PRODUCTS",data.summary?.products||0],["VERSION CONFIRMED",data.summary?.version_confirmed||0],["PRODUCT ONLY",data.summary?.product_only||0],["CVE MATCH",data.summary?.cve_matching||0]].map(x=><div><span>{x[0]}</span><b>{x[1]}</b></div>)}</div><section className="panel table-panel"><PanelHead title="Observed technology" meta="evidence-backed"/><table><thead><tr><th>Product</th><th>Version</th><th>Confidence</th><th>Evidence</th><th>Matching</th></tr></thead><tbody>{data.technologies?.map(x=><tr><td><strong>{x.product}</strong></td><td>{x.version||<span className="muted">not confirmed</span>}</td><td>{x.confidence}%</td><td>{x.evidence}</td><td><span className={"easm-state "+(x.matching.matching_allowed?"approved":"candidate")}>{x.matching.state}</span></td></tr>)}</tbody></table>{data.fingerprints?.length>0&&<div className="fingerprint-strip"><b>PASSIVE FINGERPRINT CANDIDATES</b>{data.fingerprints.map(x=><span>{x.product} · {x.confidence}% · {x.signals?.length||0} signals · version not inferred</span>)}</div>}</section></>}</>}

