function EASM({easm,onAsset}){const s=easm?.summary||{},inv=easm?.inventory||[],types=Object.entries(s.by_type||{}).sort((a,b)=>b[1]-a[1]);const [life,setLife]=useState(null);const [lifeLoading,setLifeLoading]=useState(false);const [seed,setSeed]=useState("");const [scan,setScan]=useState(null);const [aiPlan,setAiPlan]=useState(null);const [aiJudge,setAiJudge]=useState(null);const [loading,setLoading]=useState(false);const states=[["approved","APPROVED"],["candidate","CANDIDATE"],["requires_investigation","INVESTIGATE"],["dependency","DEPENDENCY"],["monitor_only","MONITOR"]];return <><PageTitle eyebrow="EXTERNAL ATTACK SURFACE MANAGEMENT" title={<>Veja o que a <i>Internet vê.</i></>} sub="Inventário externo contínuo, ownership, confiança, mudanças e contexto de risco em uma única visão."/><section className="panel lifecycle-panel"><PanelHead title="Asset Lifecycle Intelligence" meta="FIRST SEEN · CHANGES · LAST SEEN"/><div className="lifecycle-actions"><input id="lifecycle-target" placeholder="domínio autorizado"/><button onClick={async()=>{const v=document.getElementById("lifecycle-target")?.value?.trim();if(!v)return;setLifeLoading(true);const rr=await req("/api/v1/easm/lifecycle/"+encodeURIComponent(v));setLife(rr.ok?await rr.json():null);setLifeLoading(false)}}>{lifeLoading?"ANALYZING…":"ANALYZE LIFECYCLE"}</button></div>{life&&<><div className="lifecycle-kpis"><b>{life.summary?.new||0}<span>NEW</span></b><b>{life.summary?.changed||0}<span>CHANGED</span></b><b>{life.summary?.stable||0}<span>STABLE</span></b><b>{life.summary?.evidence||0}<span>EVIDENCE</span></b></div><div className="timeline">{life.assets?.filter(a=>a.state!=="stable").slice(0,8).map(a=><div className="timeline-item" key={a.fingerprint}><i/><div><strong>{a.value}</strong><span>{a.type} · {a.state} · {a.observations} observations</span><small>{a.changes?.map(ch=>ch.kind).join(" · ")||"first observation"}</small></div></div>)}</div></>}</section><section className="panel easm-discovery"><PanelHead title="Discovery Engine 2.0" meta="PASSIVE · BOUNDED · EVIDENCE-BACKED"/><div className="easm-discovery-row"><input value={seed} onChange={e=>setSeed(e.target.value)} placeholder="dominio autorizado · ex.: example.com"/><button onClick={async()=>{if(!seed.trim())return;setLoading(true);setAiPlan(null);setAiJudge(null);const rr=await req("/api/v1/easm/discover/"+encodeURIComponent(seed)+"?max_depth=2&max_assets=40");setScan(rr.ok?await rr.json():null);const ai=await req("/api/v1/discovery/ai-plan/"+encodeURIComponent(seed));setAiPlan(ai.ok?await ai.json():null);const judge=await req("/api/v1/discovery/ai-judge/"+encodeURIComponent(seed));setAiJudge(judge.ok?await judge.json():null);setLoading(false)}}>{loading?"DISCOVERING…":"DISCOVER SURFACE"}</button></div>{scan&&<div className="easm-scan-result"><b>{scan.summary?.discovered_targets||0} targets</b><span>{scan.summary?.candidate_relationships||0} relationships · {scan.summary?.evidence_count||0} evidence</span><small>{scan.nodes?.map(n=>n.target+" · "+n.reason).join("  →  ")}</small>{aiPlan?.plan&&<div className="ai-discovery-plan"><b>LOCAL AI · NEXT BEST DISCOVERY</b><p>{aiPlan.plan.summary}</p><div>{(aiPlan.plan.high_value_targets||[]).slice(0,5).map(x=><span>{typeof x==="string"?x:x.target||x.value}</span>)}</div><small>{(aiPlan.plan.next_checks||[]).slice(0,4).map(x=>typeof x==="string"?x:x.check||x.reason).join(" · ")}</small></div>}</div>}{aiJudge?.decisions?.length>0&&<div className="ai-discovery-plan"><b>LOCAL AI · EVIDENCE JUDGE</b>{aiJudge.decisions.slice(0,4).map((x,i)=><div key={i}><span>{x.subject}</span><p>{x.decision?.rationale||"Correlação analisada"}</p><small>{x.decision?.decision||"needs_review"} · confidence {x.decision?.confidence??0}{x.decision?.validation_required?" · human validation":" "}</small></div>)}</div>}</section><div className="easm-kpis">{[["TOTAL",s.total_assets||0],["EXPOSED",s.exposed_assets||0],["APPROVED",s.approved||0],["CANDIDATE",s.candidates||0],["INVESTIGATE",s.requires_investigation||0],["UNOWNED",easm?.changes?.unowned||0],["LOW CONF.",easm?.changes?.low_confidence||0],["CRITICAL",easm?.risk?.critical_findings||0]].map(x=><div key={x[0]}><span>{x[0]}</span><b>{x[1]}</b></div>)}</div><div className="grid-main"><section className="panel"><PanelHead title="Inventory confidence" meta="ownership state"/><div className="easm-state-list">{states.map(([k,l])=><div key={k}><span>{l}</span><div className="state-bar"><i style={{width:Math.min(100,((s.by_state?.[k]||0)/Math.max(1,s.total_assets))*100)+"%"}}/></div><b>{s.by_state?.[k]||0}</b></div>)}</div></section><section className="panel"><PanelHead title="Asset taxonomy" meta={types.length+" types"}/><div className="taxonomy-list">{types.length?types.slice(0,8).map(([type,count])=><div className="taxonomy-row" key={type}><div><span>{type}</span><b>{count}</b></div><div className="taxonomy-track"><i style={{width:Math.max(4,Math.round((count/Math.max(1,s.total_assets))*100))+"%"}}/></div><small>{Math.round((count/Math.max(1,s.total_assets))*100)}%</small></div>):<div className="empty-mini">Nenhum ativo classificado ainda.</div>}</div></section></div><section className="panel table-panel easm-table"><PanelHead title="External inventory" meta={inv.length+" assets"}/><table><thead><tr><th>Asset</th><th>Type</th><th>State</th><th>Confidence</th><th>Evidence</th><th>Last seen</th><th/></tr></thead><tbody>{inv.length?inv.slice(0,100).map(a=><tr key={a.id} onClick={()=>onAsset(a.id)}><td><strong>{a.value}</strong><small>{a.owner||"No owner"} · {a.environment}</small></td><td><span className="tag">{a.type}</span></td><td><span className={"easm-state "+a.state}>{a.state}</span></td><td><Meter value={a.confidence}/></td><td>{a.evidence_count}</td><td>{a.last_seen||"—"}</td><td><ChevronRight size={15}/></td></tr>):<tr className="empty-table-row"><td colSpan="7"><EmptyState title="Superfície externa ainda vazia" text="Execute o Discovery Engine para começar a construir o inventário externo." compact/></td></tr>}</tbody></table></section></>}

function Surface({assets,filtered,search,setSearch,target,setTarget,runDiscovery,discovery,onAsset}){return <><PageTitle eyebrow="ATTACK SURFACE" title={<>Mapeie o <i>desconhecido.</i></>} sub="Discovery controlado por escopo, com evidência e correlação."/><div className="discover-box"><div className="discover-copy"><div className="icon-orb"><Globe2/></div><div><h3>Run controlled discovery</h3><p>DNS · HTTP · TLS · Certificate Transparency</p></div></div><div className="discover-form"><input value={target} onChange={e=>setTarget(e.target.value)} placeholder="cliente.com.br"/><button className="primary" onClick={runDiscovery}><Search size={16}/> Descobrir</button></div>{discovery&&!discovery.loading&&<pre>{JSON.stringify(discovery,null,2)}</pre>}</div><Assets assets={filtered} search={search} setSearch={setSearch} onAsset={onAsset}/></>}
function CTEM({items,onAsset}){return <><PageTitle eyebrow="CONTINUOUS THREAT EXPOSURE MANAGEMENT" title={<>Da descoberta à <i>ação.</i></>} sub="Fila priorizada por exposição, criticidade, contexto e evidência."/><div className="ctem-board"><div className="stage"><div className="stage-head"><span>01</span><b>VALIDATE</b><em>{items.filter(x=>x.stage==="validate").length}</em></div>{items.filter(x=>x.stage==="validate").length?items.filter(x=>x.stage==="validate").map(x=><CTCard key={x.asset_id} x={x} onClick={()=>onAsset(x.asset_id)}/>):<EmptyState title="Nada para validar" text="Sem exposições aguardando validação." compact/>}</div><div className="stage hot-stage"><div className="stage-head"><span>02</span><b>REMEDIATE</b><em>{items.filter(x=>x.stage==="prioritize").length}</em></div>{items.filter(x=>x.stage==="prioritize").length?items.filter(x=>x.stage==="prioritize").map(x=><CTCard key={x.asset_id} x={x} onClick={()=>onAsset(x.asset_id)}/>):<EmptyState title="Nada para remediar" text="Nenhum item priorizado nesta etapa." compact/>}</div><div className="stage"><div className="stage-head"><span>03</span><b>RETEST</b><em>—</em></div><div className="empty-stage">Nada aguardando reteste</div></div></div></>}
function CTCard({x,onClick}){return <button className="ct-card" onClick={onClick}><div className="ct-top"><span>{x.asset}</span><b>{x.priority_score}</b></div><p>{x.next_action}</p><div><span>{x.owner||"Unowned"}</span><span>Criticality {x.criticality}/5</span></div></button>}
function Story({events,onAsset}){return <><PageTitle eyebrow="CHANGE INTELLIGENCE" title={<>Conte a história da <i>exposição.</i></>} sub="Mudanças materiais com evidência e explicabilidade."/><div className="storyline">{events.length?events.map((e,i)=><div className="story-event" key={e.asset_id+"-"+i}><div className="story-time">{e.timestamp?.slice(0,16).replace("T"," ")}</div><div className="story-line"><i/></div><button className="story-card" onClick={()=>onAsset(e.asset_id)}><div className="eyebrow">{e.event}</div><h3>{e.asset}</h3><p>{e.signals.join(" · ")}</p><div className="evidence-row"><span>confidence {e.confidence}</span>{e.explainability?.map(x=><span key={x}>{x}</span>)}</div></button></div>):<div className="panel empty-stage">Nenhuma mudança material detectada.</div>}</div></>}
function Governance({me}){
 const[users,setUsers]=useState([]),[roles,setRoles]=useState([]),[perms,setPerms]=useState([]),[scopes,setScopes]=useState([]),[userScopes,setUserScopes]=useState([]),[loading,setLoading]=useState(true),[edit,setEdit]=useState(null),[roleForm,setRoleForm]=useState({name:"",permissions:[]}),[error,setError]=useState("");
 const canManage=["admin","superadmin"].includes(me?.role);
 const load=async()=>{setLoading(true);const [u,r,p,s]=await Promise.all([req("/api/v1/users"),req("/api/v1/rbac/custom-roles"),req("/api/v1/rbac/permissions"),req("/api/v1/scopes")]);if(u.ok)setUsers(await u.json());if(r.ok)setRoles(await r.json());if(p.ok)setPerms((await p.json()).permissions||[]);if(s.ok)setScopes(await s.json());setLoading(false)};
 useEffect(()=>{load()},[]);
 const loadUserScopes=async u=>{const r=await req("/api/v1/users/"+u.id+"/scopes");setUserScopes(r.ok?await r.json():[])};
 const assignScope=async scopeId=>{if(!edit)return;const r=await req("/api/v1/users/"+edit.id+"/scopes",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({scope_id:scopeId,active:true})});if(!r.ok)return setError((await r.json()).detail||"Falha ao atribuir scope");loadUserScopes(edit)};
 const save=async e=>{e.preventDefault();const r=await req("/api/v1/users/"+edit.id,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:edit.name,role:edit.role})});if(!r.ok)return setError((await r.json()).detail||"Falha");setEdit(null);load()};
 const toggle=async u=>{const r=await req("/api/v1/users/"+u.id+"/active",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({active:!u.active})});if(!r.ok)setError((await r.json()).detail||"Falha");else load()};
 const createRole=async e=>{e.preventDefault();const r=await req("/api/v1/rbac/custom-roles",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(roleForm)});if(!r.ok)return setError((await r.json()).detail||"Falha ao criar role");setRoleForm({name:"",permissions:[]});load()};
 return <><PageTitle eyebrow="GOVERNANCE" title={<>Controle sem <i>atrito.</i></>} sub="Tenant isolation, RBAC, scopes e rastreabilidade operacional."/>
 <div className="governance-kpis"><div><span>USERS</span><b>{users.length}</b><small>{users.filter(u=>u.active).length} active</small></div><div><span>CUSTOM ROLES</span><b>{roles.length}</b><small>tenant scoped</small></div><div><span>SCOPES</span><b>{scopes.length}</b><small>discovery boundaries</small></div><div><span>SESSION ROLE</span><b className="role-value">{me?.role||"—"}</b><small>{canManage?"management enabled":"least privilege"}</small></div></div>
 <div className="grid-main"><section className="panel"><PanelHead title="Identity" meta="current session"/><div className="identity"><div className="avatar large">{(me?.name||"M").slice(0,1)}</div><div><h3>{me?.name}</h3><p>{me?.email}</p><span className="tag">{me?.role}</span><span className="tag">{me?.tenant_id}</span></div></div></section><section className="panel"><PanelHead title="Security posture" meta="platform"/><div className="security-list"><div><LockKeyhole/> Tenant isolation <b>ENFORCED</b></div><div><Eye/> Scoped discovery <b>ENFORCED</b></div><div><CheckCircle2/> Audit trail <b>ACTIVE</b></div></div></section></div>
 <section className="panel"><PanelHead title="Users" meta={users.length+" tenant users"}/>{error&&<div className="error">{error}</div>}
 {edit&&<><form onSubmit={save} className="governance-edit-form"><input required value={edit.name} onChange={e=>setEdit({...edit,name:e.target.value})}/><select value={edit.role} onChange={e=>setEdit({...edit,role:e.target.value})}>{["viewer","analyst","manager","admin",...roles.map(r=>r.name)].map(x=><option key={x}>{x}</option>)}</select><button className="primary">Salvar</button><button type="button" className="icon-btn" onClick={()=>loadUserScopes(edit)}>Scopes</button></form><div className="security-list governance-scope-list">{userScopes.map(s=><div key={s.id}><span>{s.name} · {s.pattern}</span><em>{s.active?"ACTIVE":"INACTIVE"}</em></div>)}{canManage&&<div className="scope-assign"><select defaultValue="" onChange={e=>e.target.value&&assignScope(e.target.value)}><option value="">Atribuir scope…</option>{scopes.map(s=><option key={s.id} value={s.id}>{s.name} · {s.pattern}</option>)}</select></div>}</div></>}
 <div className="security-list governance-users">{loading?<div>Carregando…</div>:users.length?users.map(u=><div key={u.id}><UserRound size={17}/><span>{u.name} · {u.email}</span><b>{u.role}</b><em>{u.active?"ACTIVE":"INACTIVE"}</em>{canManage&&<><button className="icon-btn" aria-label="Editar usuário" title="Editar usuário" onClick={()=>setEdit({...u})}>✎</button><button className="icon-btn" aria-label={u.active?"Desativar usuário":"Ativar usuário"} title={u.active?"Desativar usuário":"Ativar usuário"} onClick={()=>toggle(u)}>{u.active?"⏸":"▶"}</button></>}</div>):<EmptyState title="Nenhum usuário no tenant" text="Cadastre usuários para começar a delegar acesso." compact/>}</div></section>
 <section className="panel"><PanelHead title="Custom Roles" meta={roles.length+" tenant roles"}/>{canManage&&<form onSubmit={createRole} className="governance-role-form"><input required placeholder="Nome da role · ex.: SOC Read Only" value={roleForm.name} onChange={e=>setRoleForm({...roleForm,name:e.target.value})}/><div className="security-list">{perms.map(p=><label key={p} className="permission-option"><input type="checkbox" checked={roleForm.permissions.includes(p)} onChange={e=>setRoleForm({...roleForm,permissions:e.target.checked?[...roleForm.permissions,p]:roleForm.permissions.filter(x=>x!==p)})}/>{p}</label>)}</div><button className="primary" disabled={!roleForm.permissions.length}>Criar custom role</button></form>}<div className="security-list governance-role-list">{roles.length?roles.map(r=><div key={r.name}><Layers3 size={17}/><span>{r.name}</span><b>{r.permissions.length} permissions</b></div>):<EmptyState title="Nenhuma custom role" text="Crie roles específicas para separar responsabilidades do tenant." compact/>}</div></section>
 </>}

function Meter({value}){return <div className="meter"><i style={{width:value+"%"}}/><span>{value}%</span></div>}
function AssetDrawer({id,onClose}){const[d,setD]=useState(null);useEffect(()=>{req("/api/v1/assets/"+id).then(r=>r.json()).then(setD)},[id]);return <div className="drawer-backdrop" onClick={e=>e.target===e.currentTarget&&onClose()}><aside className="drawer">{!d?<div className="loading">Carregando Asset 360…</div>:<><div className="drawer-head"><div><div className="eyebrow">ASSET 360</div><h2>{d.asset.value}</h2><p>{d.asset.type} · {d.asset.environment} · {d.asset.status}</p></div><button className="icon-btn" onClick={onClose}><X/></button></div><div className="drawer-grid">{[["Risk",d.risk.score],["Ownership",d.ownership.score+"%"],["Blast Radius",d.blast_radius],["Evidence",d.evidence.evidence_count]].map(x=><div className="drawer-stat" key={x[0]}><span>{x[0]}</span><b>{x[1]}</b></div>)}</div><div className="drawer-section"><PanelHead title="Why this matters" meta="explainable"/>{d.risk.rationale?.map(x=><div className="reason" key={x}><span>+</span>{x}</div>)}</div><div className="drawer-section"><PanelHead title="Findings" meta={d.findings.length}/>{d.findings.map(f=><div className="finding-row" key={f.id}><div><b>{f.title}</b><span>{f.severity} · {f.status}</span></div><strong>{f.context_score}</strong></div>)}</div><div className="drawer-section"><PanelHead title="Exposure DNA" meta="fingerprint"/><code>{d.exposure_dna?.fingerprint||"—"}</code><div className="evidence-row">{d.exposure_dna?.explainability?.map(x=><span key={x}>{x}</span>)}</div></div></>}</aside></div>}
export default App;
